// 「`ws.sessions.has(...)` 里的 `sessions` 是**别人的字段**，不是这个绑定」。
//
// 词边界 `\b` **允许前面是 `.`**，于是 `ws.sessions.has(sid)` 被当成
// 变量 `sessions` 上的调用，`has` 被归到 DSH 的 `sessions` 服务头上。
//
// 实测 `dsh-recall-plugin/lib/client.js`：文件里确实有 `const sessions = ctx.sessions`
// （第 1311 行），而假站点在第 **800** 行 —— 那里 `ws.sessions` 是一个 Map 字段。
// 一次归属错误造出 5 个假方法（has/set/values/sort/reduce），
// 看起来像"DSH 少了一堆会话 API"。
//
// 判据：前面是 `.` 时只认接收者 `this`（`this.<var>.<method>(` 合法，实测 6000+ 处）；
// 别的对象上的同名字段与这个绑定无关。
export function apply(ctx) {
  const sessions = ctx.jobs;          // 合法绑定：sessions 变量 = jobs 服务
  const ws = { sessions: new Map() };
  ws.sessions.has('sid');             // ← 必须**不**被归到 jobs 头上
  return () => sessions.list();       // ← 这条是真的，必须保留
}
